          "prompt": "Ai đã giới thiệu công việc này cho bạn vậy?",
          "reference": "这个工作是谁帮你介绍的？",
          "explain": "<p><b>Giải thích:</b> Câu hỏi dùng 是……的 với từ nghi vấn 谁 ở vị trí chủ thể — đúng câu mẫu trọng tâm của Bài 4.</p><p><b>Lỗi HS Việt hay gặp:</b> Quên 是 khi câu hỏi có từ nghi vấn 谁.</p><p><b>Mẹo ghi nhớ:</b> Câu hỏi 'ai làm gì (đã xảy ra)' cũng cần đủ khung 是……的 như câu khẳng định.</p>"
