          "prompt": "这条路很长，我们走了两个小时。",
          "prompt_is_zh": true,
          "reference": "Con đường này rất dài, chúng tôi đã đi bộ hai tiếng đồng hồ.",
          "explain": "<p><b>Giải thích:</b> 长 ở đây đọc cháng, nghĩa 'dài'; 两 đứng trước lượng từ 个小时.</p><p><b>Lỗi HS Việt hay gặp:</b> Dịch nhầm 长 thành 'lâu' thay vì 'dài' trong ngữ cảnh miêu tả con đường.</p><p><b>Mẹo ghi nhớ:</b> 长 tả không gian (con đường, dòng sông) → 'dài'; tả thời gian → có thể là 'lâu'.</p>"
