          "type": "self_check",
          "prompt": "他是九月来北京工作的。",
          "prompt_is_zh": true,
          "reference": "Anh ấy đến Bắc Kinh làm việc vào tháng 9.",
          "explain": "<p><b>Giải thích:</b> 是……的 nhấn mạnh mốc thời gian (九月) của hành động 来...工作 đã xảy ra.</p><p><b>Lỗi HS Việt hay gặp:</b> Dịch thành 'Anh ấy LÀ đến Bắc Kinh làm việc vào tháng 9' — dịch thừa từ 'là' theo kiểu word-by-word.</p><p><b>Mẹo ghi nhớ:</b> 是……的 khi dịch sang tiếng Việt thường KHÔNG cần dịch từ 'là' — chỉ cần nhấn giọng vào phần được nhấn mạnh.</p>"
