          "explain": "<p><b>Giải thích:</b> Câu trả lời tự nhiên khi nhận quà: cảm ơn + hỏi lại về món quà.</p><p><b>Lỗi HS Việt hay gặp:</b> Quên câu cảm ơn, chỉ hỏi thẳng '这是什么' thiếu lịch sự.</p><p><b>Mẹo ghi nhớ:</b> Trong giao tiếp tiếng Trung, luôn cảm ơn trước khi hỏi thêm thông tin.</p>"
