          "explain": "<p><b>Giải thích:</b> Trả lời theo đúng khung 是……的 của câu hỏi.</p><p><b>Lỗi HS Việt hay gặp:</b> Trả lời cụt lủn chỉ '我姐姐' thiếu 是...的.</p><p><b>Mẹo ghi nhớ:</b> Trả lời câu hỏi 是……的 nên lặp lại đúng khung ngữ pháp của câu hỏi.</p>"
