          "explanation": "<p><b>Giải thích:</b> Đoạn văn nêu rõ: '爸爸送给女儿一个礼物，是一本书。'</p><p><b>Vì sao các đáp án khác sai:</b> 蛋糕/草莓/汉堡 chỉ là món ăn trong bữa tiệc, không phải quà tặng.</p><p><b>Lỗi HS Việt hay gặp:</b> Chọn nhầm món ăn xuất hiện gần cuối đoạn (汉堡) vì đọc sót thông tin ở giữa.</p><p><b>Mẹo ghi nhớ:</b> Đọc kỹ động từ 送给 (tặng cho) để xác định đúng 'món quà' chứ không phải 'món ăn'.</p>",
