          "answer": null,
          "explanation": "<p><b>Giải thích:</b> Đoạn văn dùng cấu trúc 是……的 để nêu rõ mốc thời gian mua sách — câu gốc: '这本书是爸爸昨天买的。'</p><p><b>Lỗi HS Việt hay gặp:</b> Trả lời thiếu 是……的 khi trích dẫn lại câu trong bài, chỉ viết '昨天'.</p><p><b>Mẹo ghi nhớ:</b> Khi trả lời câu hỏi thời gian có 是……的 trong bài, nên giữ nguyên cấu trúc đó trong câu trả lời.</p>",
