          "answer": "C",
          "explanation": "<p><b>Giải thích:</b> Đoạn văn nêu: '这个工作是王方帮我介绍的。' — thông tin trực tiếp từ câu đầu đoạn văn.</p><p><b>Vì sao các đáp án khác sai:</b> 同事 chỉ giúp giải quyết vấn đề, 快递员 giao hàng, 丈夫 không xuất hiện trong bài.</p><p><b>Lỗi HS Việt hay gặp:</b> Chọn 同事 vì nhân vật này xuất hiện nhiều lần trong đoạn.</p><p><b>Mẹo ghi nhớ:</b> Câu hỏi về 'công việc do ai giới thiệu' luôn nằm ở đầu đoạn giới thiệu bối cảnh.</p>",
