          "skill": "reading",
          "type": "mcq",
          "prompt": "医生说，什么对健康好？",
          "answer": "B",
          "explanation": "<p><b>Giải thích:</b> Đoạn văn nêu: '医生说，按时睡觉、常常运动对健康非常好。'</p><p><b>Vì sao các đáp án khác sai:</b> Các đáp án còn lại đều là hành vi KHÔNG tốt cho sức khỏe được nhắc đến trong bài (làm việc khuya, không vận động).</p><p><b>Lỗi HS Việt hay gặp:</b> Chọn nhầm D vì từ '晚' xuất hiện gần đó, nhưng đó là mô tả việc XẤU, không phải lời khuyên của bác sĩ.</p><p><b>Mẹo ghi nhớ:</b> Tìm đúng câu có '医生说' để xác định lời khuyên, tránh nhầm với các câu mô tả khác.</p>",
