          "answer": null,
          "explanation": "<p><b>Giải thích:</b> Đoạn văn nêu rõ nguyên nhân bằng câu: '昨天我工作到很晚才睡觉，今天早上起床的时候觉得很累。'</p><p><b>Lỗi HS Việt hay gặp:</b> Trả lời chung chung 'vì không ngủ đủ' mà không nêu rõ lý do làm việc khuya.</p><p><b>Mẹo ghi nhớ:</b> Câu hỏi 'vì sao' luôn có tín hiệu nhân quả gần đó — tìm từ 昨天 để định vị đúng đoạn.</p>",
