          "reference": "我是去年开始学习中文的。(đáp án mẫu, có thể thay mốc thời gian phù hợp bản thân)",
          "explain": "<p><b>Giải thích:</b> Dùng 是……的 nhấn mạnh mốc thời gian bắt đầu — đúng cấu trúc trả lời cho câu hỏi thời gian của việc đã xảy ra.</p><p><b>Lỗi HS Việt hay gặp:</b> Quên đưa 是 vào đầu phần trả lời.</p><p><b>Mẹo ghi nhớ:</b> Trả lời câu hỏi '什么时候……的' luôn lặp lại khung 是……的 trong câu trả lời.</p><p><b>Ví dụ bổ sung:</b> 我是三月开始工作的。</p>"
