          "explain": "<p><b>Giải thích:</b> 已经 + V + 了 nhấn mạnh việc đã hoàn thành — đúng cấu trúc và đúng tình huống giao tiếp.</p><p><b>Lỗi HS Việt hay gặp:</b> Quên 了 cuối câu.</p><p><b>Mẹo ghi nhớ:</b> Thông báo một việc vừa hoàn thành luôn cần cặp 已经……了.</p><p><b>Ví dụ bổ sung:</b> 今天，我已经吃完饭了。</p>"
