          "reference": "我是去年九月开始学习中文的。那时候，我觉得中文很难，但是我很喜欢。现在，我已经学了一年多了。我认识了很多汉字，也认识了很多新朋友。我希望以后可以说得更好。",
          "explain": "<p><b>Giải thích:</b> Đoạn văn mẫu sử dụng đủ 2 cấu trúc trọng tâm: 是……的 (mở đầu) và 已经……了 (giữa/cuối đoạn).</p><p><b>Tiêu chí đánh giá:</b> đảm bảo đúng yêu cầu ngữ pháp, mạch lạc, có mở-thân-kết đơn giản.</p><p><b>Lỗi HS Việt hay gặp:</b> Viết đoạn văn chỉ kể sự kiện mà quên lồng ghép 2 cấu trúc ngữ pháp được yêu cầu.</p><p><b>Mẹo ghi nhớ:</b> Trước khi viết, gạch chân trong đề bài các cấu trúc bắt buộc để không bỏ sót.</p>"
